  #[using="IMG AMS NEED0 MPIINIT"] Lemma A_ecp_keypair_init_walk : ecp_keypair_init_stmtA asegs R HIA MT A_ECP_KEYPAIR_INIT.
  Proof.
    unfold ecp_keypair_init_stmtA, A_ECP_KEYPAIR_INIT, ECP_KEYPAIR_SIZE.
    intros until junk. intros HH HK AL8 POS ST LOS SLO TOP SPA DS MI OA CWA ->.
    pose proof (hcs_ok asegs R HIA h) as CSOK.
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    pose proof (art_alwf asegs R HIA) as ALWF'. unfold al_wf in ALWF'.
    pose proof IMG as IMG'. unfold asan_img_ok in IMG'.
    pose proof (art_lo asegs R HIA) as ALO. pose proof alloc_ceiling_pos as ACP.
    pose proof (hcs_stack asegs R HIA h) as SCS0.
    pose proof (hm_top asegs R HIA h LB LF m HH) as HTOP.
    pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. cbn [Z.pow Z.of_N Pos.pow] in SPR.
    assert (LO0 : 0 <= lo) by lia.
    assert (SCS : crange (hcs asegs R HIA h) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| lia| lia]).
    pose proof (rw_cells_bound _ _ _ _ HK) as GB. cbn [cells_size csize Nat.add] in GB.
    assert (JLK : length junk = 256%nat) by (destruct HK as [[WF _] _]; cbn in WF; destruct WF as [WF _]; exact WF).
    destruct (kp_chunks_of_bytes _ _ _ _ HK) as (HG & R1 & R2 & R3 & R4). clear HK.
    set (junkg := gsub junk 0 192) in *.
    apply mpi_cells_of_bytes in R1. apply mpi_cells_of_bytes in R2. apply mpi_cells_of_bytes in R3. apply mpi_cells_of_bytes in R4.
    pose proof (munch_refl [(A, A + 256); (lo, bv_unsigned sp)] m) as MU.
    pose proof (wmono_refl asegs m) as WM.
    carve_frame 16%nat ST.
    unfold mpi_cells in R1, R2, R3, R4.
    (* [comment removed for export] *)
    zstep. zstep. zstep.
    zstep. if_cases K0; zify_cond K0; [exfalso; rewrite ?unsigned_lit in K0 by qlia; clear - K0 POS; lia|]. clear K0.
    (* [comment removed for export] *)
    assert (AL7 : Z.land A 7 = 0)
      by (change 7 with (Z.ones 3); rewrite Z.land_ones by lia; first [exact AL8 | clear - AL8; Z.div_mod_to_equations; lia]).
    zstep. zstep. zstep. if_cases KA; zify_cond KA; [exfalso; clear - KA AL7; rewrite ?AL7 in KA; rewrite ?Zmod_0_l in KA; lia|]. clear KA.
    (* [comment removed for export] *)
    zstep. zstep.
    pose proof (A_ecp_group_init_spec R HIA MT IMG AMS NEED0) as SG. unfold ecp_group_init_stmtA, A_ECP_GROUP_INIT, ECP_GROUP_SIZE in SG.
    lazymatch goal with
    | |- evtA ?sg _ _ _ (MS _ _ _ _ _ ?mx _) =>
        eapply evtA_cut;
        [ eapply SG with (h := h) (LB := LB) (LF := LF) (A := A) (lo := lo) (LBg := LBg) (junk := junkg);
          rewrite ?(unsigned_lit (bv_unsigned sp + -16)) by qlia;
          try eassumption; try reflexivity;
          try (eapply aobj_sub; [eassumption| qlia| qlia]);
          try (clear - DS; lia);
          try (clear - SPA; Z.div_mod_to_equations; lia);
          try (eapply (client_wrange_weak L); [exact CWA| intros b Hb; exact Hb| qlia| qlia| qlia]);
          try qlia
        | unfold ecp_group_init_postA, ECP_GROUP_SIZE;
          rewrite ?(unsigned_lit (bv_unsigned sp + -16)) by qlia;
          post_callA sg mx ]
    end.
    clear SG.
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "GROUPINIT-LEFT:" g end.
    (* [comment removed for export] *)
    match goal with H : ecp_group_at _ _ _ _ A _ |- _ => rename H into GIc end.
    unfold ecp_group_at, ecp_point_at in GIc.
    destruct GIc as (HD & _ & _ & _ & _ & _ & _ & MP & MA & MB & (_ & _ & _ & MX & MY & MZ) & MN & HT & _).
    (* [comment removed for export] *)
    pose proof MPIINIT as SPI. unfold mpi_init_stmtA, A_MPI_INIT_ in SPI.
    (* [comment removed for export] *)
    apply proj1 in MP. apply proj1 in MA. apply proj1 in MB. apply proj1 in MX. apply proj1 in MY. apply proj1 in MZ. apply proj1 in MN.
    cbn [md_addr mpd_init grp_init g_P g_A g_B g_G g_N pt_X pt_Y pt_Z pt_init md_p md_sg md_n md_pad] in MP, MA, MB, MX, MY, MZ, MN.
    replace (A + 56 + 16) with (A + 72) in MY by (clear; lia). replace (A + 56 + 32) with (A + 88) in MZ by (clear; lia).
    unfold mpi_cells in MP, MA, MB, MX, MY, MZ, MN.
    (* [comment removed for export] *)
    unfold grp_tail_cells, grp_init in HT. cbn [g_pbits g_nbits g_h g_hpad g_modp g_tpre g_tpost g_tdata g_T g_Tsize] in HT.
    unfold grp_head_cells, grp_init in HD. cbn [g_id g_idpad] in HD.
    (* [comment removed for export] *)
    initcallA SPI HIA h (A + 192) lo SCS0 OA (bv_unsigned sp + -16).
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "AFTER-INIT1:" g end.
    initcallA SPI HIA h (A + 208) lo SCS0 OA (bv_unsigned sp + -16).
    initcallA SPI HIA h (A + 224) lo SCS0 OA (bv_unsigned sp + -16).
    match goal with H : stk _ _ lo _ |- _ => rename H into ST end.
    (* [comment removed for export] *)
    zstep. zstep. zstep. zstep.
    release_frame FR ST (bv_unsigned sp).
    zstep.
    callxA_sp (bv_unsigned sp)
        (eapply SPI with (CS := hcs asegs _ HIA h) (X := A + 240) (lo := lo);
         try eassumption; try reflexivity;
         first [ exact (art_alwf asegs _ HIA)
               | eapply hm_abase; eassumption
               | eapply aobj_sub; [eassumption| qlia| qlia]
               | eapply crange_sub; [exact SCS0| qlia| qlia]
               | qlia
               | pqlia
               | match goal with |- ?g => idtac "TAILCALL-LEFT:" g end ]).
    unfold mpi_cells in *. clear SPI.
    finish; try eassumption; try (clear - SLO NEED0; lia).
    all: match goal with |- ecp_keypair_at _ _ _ _ _ _ => idtac | |- ?g => idtac "FINISH-LEFT:" g end.
    eapply ecp_keypair_at_init; [| eassumption| eassumption| eassumption| eassumption].
    eapply ecp_group_at_init; [exact HD | exact AL8 | exact POS | eassumption | eassumption | eassumption | eassumption | eassumption | eassumption | eassumption | exact HT].
  Qed.
  Local Ltac2 Set LiaOrc.tbl := fun () => "". (* [comment removed for export] *)
End Walk.

